static void sensor_buffer_push(uint16_t sample)
{
  if (sensor_ring_count < SENSOR_RING_SIZE)
  {
    sensor_ring_buffer[sensor_ring_head] = sample;
    sensor_ring_sum += sample;
    sensor_ring_count++;
  }
  else
  {
    sensor_ring_sum -= sensor_ring_buffer[sensor_ring_head];
    sensor_ring_buffer[sensor_ring_head] = sample;
    sensor_ring_sum += sample;
  }

  sensor_ring_head++;
  if (sensor_ring_head >= SENSOR_RING_SIZE)
  {
    sensor_ring_head = 0U;
  }

  sensor_sample = sample;
  sensor_average = sensor_ring_sum / ((sensor_ring_count == 0U) ? 1U : sensor_ring_count);
}

static uint32_t get_hclk_frequency(void)
{
  uint32_t cfgr = RCC_CFGR;
  uint32_t sysclk_source = (cfgr >> 2) & 0x3U;
  uint32_t sysclk_hz;
  uint32_t hpre;

  switch (sysclk_source)
  {
    case 0U:
      sysclk_hz = 8000000U;
      break;
    case 1U:
      sysclk_hz = 8000000U;
      break;
    case 2U:
    {
      uint32_t pllmul = ((cfgr >> 18) & 0xFU) + 2U;
      uint32_t pllsrc = (cfgr >> 16) & 0x1U;
      uint32_t pllxtpre = (cfgr >> 17) & 0x1U;
      uint32_t pll_input_hz = 8000000U;

      if (pllsrc != 0U)
      {
        pll_input_hz = (pllxtpre != 0U) ? 4000000U : 8000000U;
      }

      sysclk_hz = pll_input_hz * pllmul;
      break;
    }
    default:
      sysclk_hz = 8000000U;
      break;
  }

  hpre = (cfgr >> 4) & 0xFU;
  if (hpre < 8U)
  {
    return sysclk_hz;
  }

  switch (hpre)
  {
    case 8U: return sysclk_hz / 2U;
    case 9U: return sysclk_hz / 4U;
    case 10U: return sysclk_hz / 8U;
    case 11U: return sysclk_hz / 16U;
    case 12U: return sysclk_hz / 64U;
    case 13U: return sysclk_hz / 128U;
    case 14U: return sysclk_hz / 256U;
    case 15U: return sysclk_hz / 512U;
    default: return sysclk_hz;
  }
}

static void bluepill_led_init(void)
{
  RCC_APB2ENR |= RCC_IOPCEN;
  GPIOC_CRH &= ~(GPIO_CRH_MODE13_MASK | GPIO_CRH_CNF13_MASK);
  GPIOC_CRH |= (2UL << GPIO_CRH_MODE13_Pos);
  GPIOC_ODR |= GPIO_ODR_PIN13;
}

static void systick_init(void)
{
  uint32_t hclk = get_hclk_frequency();
  uint32_t reload = (hclk / RTOS_TICK_RATE_HZ) - 1U;

  SYSTICK_CTRL = 0U;
  SCB_SHPR3 = (SCB_SHPR3 & 0x0000FFFFUL) | SCB_SHPR3_PENDSV_LOWEST | SCB_SHPR3_SYSTICK_LOWEST;
  SYSTICK_LOAD = reload;
  SYSTICK_VAL = 0U;
  SYSTICK_CTRL = SYSTICK_CTRL_CLKSOURCE | SYSTICK_CTRL_TICKINT | SYSTICK_CTRL_ENABLE;
  __asm volatile ("cpsie i");
}

