static VOID blink_thread_entry(ULONG thread_input)
{
  (void)thread_input;

  for (;;)
  {
    (void)tx_semaphore_get(&button_alert_semaphore, TX_WAIT_FOREVER);

    alert_ticks_remaining = ALERT_HOLD_TICKS;
    oled_render_dashboard();

    GPIOC_BSRR = (1UL << 29);
    tx_thread_sleep(ALERT_BLINK_DELAY_TICKS);
    GPIOC_BSRR = GPIO_BSRR_BS13;
    tx_thread_sleep(ALERT_BLINK_DELAY_TICKS);
    GPIOC_BSRR = (1UL << 29);
    tx_thread_sleep(ALERT_BLINK_DELAY_TICKS);
    GPIOC_BSRR = GPIO_BSRR_BS13;

    blink_count++;
  }
}

static VOID monitor_thread_entry(ULONG thread_input)
{
  ULONG last_sensor_loops = 0U;
  ULONG stalled_count = 0U;
  UINT stall_reported = TX_FALSE;

  (void)thread_input;

  uart_send_string_locked("Monitor thread ready\r\n");

  for (;;)
  {
    if (sensor_loop_count == last_sensor_loops)
    {
      stalled_count++;
      if ((stalled_count >= MONITOR_STALL_THRESHOLD) &&
          (stall_reported == TX_FALSE) &&
          (uart_try_lock() == TX_SUCCESS))
      {
        usart1_send_string("MON stalled ");
        usart1_send_monitor_snapshot();
        uart_unlock();
        stall_reported = TX_TRUE;
      }
    }
    else
    {
      last_sensor_loops = sensor_loop_count;
      stalled_count = 0U;
      stall_reported = TX_FALSE;
    }

    delay_cycles(MONITOR_DELAY_CYCLES);
  }
}

static VOID data_sensor_thread_entry(ULONG thread_input)
{
  char received_char;
  uint16_t sample;
  uint8_t button_previous = 1U;

  (void)thread_input;

  data_sensor_peripherals_init();

  for (;;)
  {
    sensor_loop_count++;
    sample = adc_read_sample();
    sensor_buffer_push(sample);

    {
      uint8_t button_current = ((GPIOA_IDR & (1UL << 1)) != 0U) ? 1U : 0U;
      if ((button_previous == 1U) && (button_current == 0U))
      {
        button_pressed = 1U;
      }
      button_previous = button_current;
    }

    if (button_pressed != 0U)
    {
      button_pressed = 0U;
      button_state ^= 1U;
      uart_send_string_locked("Button pressed\r\n");
      (void)tx_semaphore_put(&button_alert_semaphore);
    }

    if (uart_try_lock() == TX_SUCCESS)
    {
      usart1_send_string("ADC: ");
      usart1_send_uint32(sensor_sample);
      usart1_send_string(" AVG: ");
      usart1_send_uint32(sensor_average);
      usart1_send_string("\r\n");
      uart_unlock();
    }

    if (usart1_data_available() != 0U)
    {
      received_char = usart1_receive_char();
      if (uart_try_lock() == TX_SUCCESS)
      {
        usart1_send_string("Received: ");
        usart1_send_char(received_char);
        usart1_send_string("\r\n");
        uart_unlock();
      }
    }

    oled_render_dashboard();

    if (alert_ticks_remaining > 0U)
    {
      alert_ticks_remaining--;
    }

    tx_thread_sleep(SENSOR_SAMPLE_DELAY_TICKS);
  }
}

